"contenttype":"jsjQuery","contents":"// Listener for ESignTxnCompleted_MoveIn
document.addEventListener('ESignTxnCompleted_MoveIn', () => {
 const autoAdvanceButtonMoveIn = document.querySelector("[data-button-id*='AutoAdvance_To_Nexttask_MoveIn']");
 const autoAdvanceButtonMoveInReset = document.querySelector("[data-button-id*='MoveIn_Reset']");
 const showProcessTimerButtonMoveIn = document.querySelector("[data-button-id*='Show_ProcessTimer_MoveIn']");
 if (autoAdvanceButtonMoveIn) {
 autoAdvanceButtonMoveIn.click();
 console.info("ESignTxnCompleted_MoveIn event handler executed: AutoAdvance_To_Nexttask_MoveIn button clicked.");
 } else {
 console.warn("ESignTxnCompleted_MoveIn event handler: AutoAdvance_To_Nexttask_MoveIn button not found.");
 }

 if (autoAdvanceButtonMoveInReset) {
 autoAdvanceButtonMoveInReset.click();
 console.info("ESignTxnCompleted_MoveIn event handler executed: MoveIn_Reset button clicked.");
 } else {
 console.warn("ESignTxnCompleted_MoveIn event handler: MoveIn_Reset button not found.");
 }

 if (showProcessTimerButtonMoveIn) {
 showProcessTimerButtonMoveIn.click();
 console.log("ESignTxnCompleted_MoveIn event handler: Show_ProcessTimer_MoveIn button clicked.");
 } else {
 console.warn("ESignTxnCompleted_MoveIn event handler: Show_ProcessTimer_MoveIn button not found.");
 }
});

